package br.senai.plataformadigital.academicpi;
import br.senai.plataformadigital.auth.api.authorization.*; import java.util.UUID; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="spring.datasource.url") public class InstitutionalAuditAuthorizationPolicy implements AuthorizationPolicyContribution {private final JdbcTemplate jdbc;public InstitutionalAuditAuthorizationPolicy(JdbcTemplate jdbc){this.jdbc=jdbc;}public boolean supports(String action){return "READ_INSTITUTIONAL_AUDIT".equals(action);}public boolean permits(AuthenticatedSubject s,AuthorizationRequest r){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS (SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.name='COORDENACAO' AND ur.scope_type='GLOBAL')",Boolean.class,UUID.fromString(s.id())));}}
